// Package sqlite is rewards' Repo on the platform database (queries.sql, generated by sqlc).
package sqlite

import (
	"context"
	"database/sql"
	"time"

	"github.com/IhebBelhadj/opsforge-academy/academy/internal/platform/sqlite"
	"github.com/IhebBelhadj/opsforge-academy/academy/internal/rewards"
)

// Repo implements rewards.Repo.
type Repo struct {
	q *Queries
}

var _ rewards.Repo = (*Repo)(nil)

// NewRepo uses the open database db.
func NewRepo(db *sql.DB) *Repo { return &Repo{q: New(db)} }

// Awards are user's awards: badge id → when.
func (r *Repo) Awards(ctx context.Context, user int64) (map[string]time.Time, error) {
	rows, err := r.q.UserAwards(ctx, user)
	if err != nil {
		return nil, err
	}
	out := make(map[string]time.Time, len(rows))
	for _, row := range rows {
		at, err := sqlite.ParseTime(row.AwardedAt)
		if err != nil {
			return nil, err
		}
		out[row.BadgeID] = at
	}
	return out, nil
}

// Award records a badge for user; false when it was already awarded.
func (r *Repo) Award(ctx context.Context, user int64, badge string, at time.Time) (bool, error) {
	n, err := r.q.InsertAward(ctx, InsertAwardParams{UserID: user, BadgeID: badge, AwardedAt: sqlite.FormatTime(at)})
	return n == 1, err
}
